 HIST=rowsOf('history');ACTS=rowsOf('acts');ACT=byId(ACTS);FUS=rowsOf('fus');FU=byId(FUS);CONFS=rowsOf('confs');CONF=byId(CONFS);BRIEFS=rowsOf('briefs');BRIEF=byId(BRIEFS);SIGS=rowsOf('signals');SIG=byId(SIGS);PROFILES=rowsOf('profiles');
 CAT_ROWS=rowsOf('cats').map(c=>({...c,vals:(parseJSON(c.values)||[]).map(String).filter(Boolean)}));VIEWS=rowsOf('views').map(v=>({...v,flt:parseJSON(v.filters)||{}}));
 REPORTS=rowsOf('reports').sort(byDateDesc('run_on'));
 settingsRow=rowsOf('settings')[0]||null;SET=settingsRow||{};
 CAD=CADENCE.includes(REPORTS[0]&&REPORTS[0].cadence)?REPORTS[0].cadence:'weekly';STALLED=Math.max(1,Math.round(num(SET.stalled_days,21)));
 STAGECFG=OBJ(SET.stage_config);OPTCFG=OBJ(SET.option_lists);PREF=OBJ(SET.preferences);TEAM_IDS=OBJ(SET.team_members);
 STAGES=STD_STAGES.slice();STAGE_LABEL={...STAGE_LABEL_STD};STAGE_ANCHOR={};
 for(const c of Array.isArray(STAGECFG.custom)?STAGECFG.custom.slice(0,10):[]){const k=String(c&&c.key||''),a=String(c&&c.after||'');if(!/^[a-z][a-z0-9_]{0,40}$/.test(k)||STAGES.includes(k)||!PIPE.includes(a)||a==='signed')continue;STAGES.splice(STAGES.indexOf(a)+1+STAGES.filter(x=>STAGE_ANCHOR[x]===a).length,0,k);STAGE_ANCHOR[k]=a;STAGE_LABEL[k]=textOf(c.label,60)||cap(k);}
 for(const [k,v] of Object.entries(OBJ(STAGECFG.labels)))if(STAGES.includes(k)&&textOf(v,60))STAGE_LABEL[k]=textOf(v,60);
 STAGE_HIDDEN=(Array.isArray(STAGECFG.hidden)?STAGECFG.hidden:[]).map(String).filter(k=>STAGES.includes(k)&&!['identified','signed','lost'].includes(k));
 ACT_KINDS=ACT_KINDS_STD.slice();ACT_LABEL={...ACT_LABEL_STD};ACT_HIDDEN=applyList(ACT_KINDS,ACT_LABEL,OPTCFG.activity_kinds);
 DEAL_TYPES=DEAL_TYPES_STD.slice();DEAL_LABEL={};DEAL_HIDDEN=applyList(DEAL_TYPES,DEAL_LABEL,OPTCFG.deal_types);
 PAGE_SIZE=Math.min(50,Math.max(10,num(PREF.page_size,null)||num(cfg.pageSize,25)||25));OV_HIDDEN=Array.isArray(PREF.overview_hidden)?PREF.overview_hidden.map(String):[];
 const raw=parseJSON(SET.custom_fields);
 CFS=(Array.isArray(raw)?raw:[]).slice(0,40).map(f=>f&&typeof f==='object'?{role:CF_TABLE[f.table],key:String(f.key||''),label:textOf(f.label,60)||cap(f.key),kind:CF_KINDS.includes(f.kind)?f.kind:'text',options:Array.isArray(f.options)?f.options.map(x=>textOf(x,80)).filter(Boolean):[],column:f.column!==false,filter:!!f.filter}:null).filter(f=>f&&f.role&&roleMap[f.role]&&roleMap[f.role].fields[f.key]&&!S[f.role].some(x=>x.key===f.key)&&(f.kind!=='select'||f.options.length));
 const lr=parseJSON(SET.lost_reasons);LOST=Array.isArray(lr)&&lr.length?lr.map(v=>textOf(v,120)).filter(Boolean):LOST_DEFAULT;
 TEAM=[...new Set(list(SET.team).concat(Object.keys(TEAM_IDS)).concat(OPPS.map(o=>String(o.owner||'')),FUS.map(f=>String(f.owner||''))).map(x=>x.trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
