function editorPanel(){const x=st.editor;if(!x)return '';const role=x.role,d=x.draft,fixed=x.mode==='create'?presetFor(role,x.ctx):{};
 const ctl=f=>{const v=d[f.key]===null||d[f.key]===undefined?'':d[f.key],a=' name="'+f.key+'" data-action="draft:'+f.key+'"'+(f.required?' required':''),lab='<span>'+esc(f.label)+(f.required?' *':'')+'</span>';
  if(f.kind==='boolean')return '<label class="pt-check"><input type="checkbox"'+a+(bool(v)?' checked':'')+'><span>'+esc(f.label)+'</span></label>';
  let c;if(f.kind==='select')c='<select'+a+'><option value="">—</option>'+f.options.map(o=>'<option value="'+esc(o)+'"'+(String(v)===o?' selected':'')+'>'+esc(role==='opps'&&f.key==='direction'?DIR_LABEL[o]:role==='acts'&&f.key==='kind'?ACT_LABEL[o]||o:cap(o))+'</option>').join('')+'</select>';
  else if(f.kind==='ref')c='<select'+a+'><option value="">—</option>'+rowsOf(f.ref).slice().sort(byName).map(o=>'<option value="'+esc(o.id)+'"'+(String(v)===o.id?' selected':'')+'>'+esc(f.ref==='programs'?progLong(o.id):o.name||'Unnamed')+'</option>').join('')+'</select>';
  else if(f.kind==='longtext')c='<textarea rows="4"'+a+'>'+esc(v)+'</textarea>';
  else if(f.key==='owner'&&TEAM.length)c='<select'+a+'><option value="">—</option>'+TEAM.concat(v&&!TEAM.includes(v)?[v]:[]).map(n=>'<option'+(n===v?' selected':'')+'>'+esc(n)+'</option>').join('')+'</select>';
  else c='<input type="'+(f.kind==='number'?'number':f.kind==='date'?'date':'text')+'"'+(f.kind==='number'?' step="any" min="0"':'')+a+' value="'+esc(v)+'">';
  return '<label class="k-field">'+lab+c+'</label>';};
 const ck=(k,lab)=>'<label class="pt-check"><input type="checkbox" name="'+esc(k)+'" data-action="draft:'+esc(k)+'"'+(bool(d[k])?' checked':'')+'><span>'+esc(lab)+'</span></label>';
 let extra='';
 if(role==='opps'){extra=history(d.organization_id,x.id);if(x.mode==='create'){extra+=CATS.filter(c=>c.values.length).map(c=>c.multiple?group(c.name,c.values.map(v=>ck('tag_'+c.name+'__'+v,v)).join('')):'<label class="k-field"><span>'+esc(c.name)+'</span><select name="tag_'+esc(c.name)+'" data-action="draft:tag_'+esc(c.name)+'"><option value="">None</option>'+c.values.map(v=>'<option value="'+esc(v)+'"'+(d['tag_'+c.name]===v?' selected':'')+'>'+esc(v)+'</option>').join('')+'</select></label>').join('');
  const ppl=PEOPLE.filter(p=>p.organization_id===(fixed.organization_id||d.organization_id));if(ppl.length)extra+=group('Contacts',ppl.map(p=>ck('c_'+p.id,p.name)).join(''));}}
 if(role==='people')extra=history(fixed.organization_id||d.organization_id);
 if(role==='confs')extra=group('Deadlines',[1,2,3].map(i=>'<div class="pt-pair">'+'<label class="k-field"><span>Deadline '+i+'</span><input name="dl'+i+'_label" data-action="draft:dl'+i+'_label" value="'+esc(d['dl'+i+'_label']||'')+'"></label><label class="k-field"><span>Date</span><input type="date" name="dl'+i+'_date" data-action="draft:dl'+i+'_date" value="'+esc(d['dl'+i+'_date']||'')+'"></label></div>').join(''));
 if(role==='profiles'){const docs=docsList();extra=group('Directions',DIRS.map(k=>ck('dir_'+k,DIR_LABEL[k])).join(''))+group('Deal types',DEAL_TYPES.filter(k=>!DEAL_HIDDEN.includes(k)||bool(d['deal_'+k])).map(k=>ck('deal_'+k,DEAL_LABEL[k])).join(''))+group('Non-confidential materials (current versions)',docs.docs.length?docs.docs.slice(0,40).map(z=>ck('doc_'+z.versionId,docTitle(z)+ver(z.version))).join(''):note2(docs.state==='ready'?'No documents yet.':'Documents appear in the saved app; the current list is kept.'));}
 const fs=editable(role).filter(f=>!has(fixed,f.key));
 return kit.panel({title:(x.mode==='create'?'New ':'Edit ')+ROLE_LABEL[role],close:'close',body:formHtml('save-record',fs.map(ctl).join('')+extra,submit(x.mode==='create'?'Add':'Save',canWrite(role))+btn('Cancel','close')+(x.mode==='edit'?wbtn(role,'Delete','delete:'+role+':'+x.id):''))});}

/* The page. */
const MAIN={overview,pipeline,partners,conferences,activity:activityScreen,research,lists:listsScreen,settings:settingsScreen};
let main,overlay='';
if(PENDING)main='<p class="k-muted" aria-busy="true">Loading…</p>';
else{try{main=MAIN[st.section]();}catch(e){main='<p class="pt-flag pt-warn">This screen could not be shown: '+esc(String(e&&e.message||e))+'</p>';}
 try{overlay=editorPanel()||sidePanel();}catch(e){overlay='';note('error','This panel could not be shown: '+String(e&&e.message||e).slice(0,200));}}
const undoBar=st.undo&&inp.saved?'<div class="k-row pt-undo">'+kit.undo([{undoId:'last',label:st.undo}])+'</div>':'';
const layout=kit.layout(kit.nav(screens,st.section,{side:true,label:'Partnerships screens'}),undoBar+main,{side:true});
const html=kit.page((overlay?'<div inert>'+layout+'</div>':layout)+overlay);
const out={html,css:PARTNERSHIPS_CSS,state:st};
if(NOTICE)out.notice=NOTICE;
const nextCtx={me:st.me||null,conf:st.confId||null};if(inp.saved&&JSON.stringify(nextCtx)!==JSON.stringify({me:ctx.me||null,conf:ctx.conf||null}))out.context=nextCtx;
return out;
